          },
          "to_ccy": {
            "type": "string",
            "description": "Three-letter ISO code of the target currency (USD, EUR, GBP, JPY, or INR)."
          }
        },
        "required": [
          "amount",
          "from_ccy",
          "to_ccy"
        ]
      },
      "return": {
        "type": "number",
        "description": "Converted monetary amount in the target currency, rounded to 2 decimal places."
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "compound_interest",
      "description": "Compute the final total balance (principal plus interest) under compound interest.\n\nUses the standard formula A = P * (1 + r / n) ** (n * t), where r is\nannual_rate_pct / 100, n is compounds_per_year, and t is years.",
      "parameters": {
        "type": "object",
        "properties": {
          "principal": {
            "type": "number",
            "description": "Initial principal amount invested or deposited."
          },
          "annual_rate_pct": {
            "type": "number",
            "description": "Nominal annual interest rate as a percentage (e.g. 5.5 for 5.5%)."
