        "required": [
          "principal",
          "annual_rate_pct",
          "years",
          "compounds_per_year"
        ]
      },
      "return": {
        "type": "number",
        "description": "Final maturity balance including principal and accrued interest, rounded to 2 decimal places."
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "percent_change",
      "description": "Calculate the percentage change from an old value to a new value.\n\nUses ((new - old) / old) * 100. For example, old=100 and new=125 returns 25.0.",
      "parameters": {
        "type": "object",
        "properties": {
          "old": {
            "type": "number",
            "description": "Original baseline value (must be non-zero)."
          },
          "new": {
            "type": "number",
            "description": "New updated value to compare against the baseline."
          }
        },
        "required": [
          "old",
          "new"
        ]
      },
      "return": {
        "type": "number",
        "description": "Signed percentage change from old to new, rounded to 2 decimal places."
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "loan_payment",
      "description": "Compute the fixed monthly payment for a fully amortizing loan.\n\nUses M = P * (i * (1 + i)**m) / ((1 + i)**m - 1) where i is the monthly\ninterest rate (annual_rate_pct / 100 / 12) and m is the loan term in months.",
      "parameters": {
        "type": "object",
        "properties": {
          "principal": {
            "type": "number",
            "description": "Total loan principal borrowed."
          },
          "annual_rate_pct": {
            "type": "number",
            "description": "Annual percentage interest rate (e.g. 6.5 for 6.5% APR)."
          },
          "months": {
            "type": "integer",
            "description": "Total repayment period in months (must be positive)."
